function showToast(message){const toast=document.querySelector('.toast');if(!toast)return;toast.textContent=message;toast.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove('show'),3800)}

const FieldmarkDemo=(()=>{
  const key='fieldmark-demo-v3';
  const defaults={
    tools:[{id:'m18-drill',name:'Milwaukee M18 Drill',label:'FM-1842',place:'Jordan Hill · Oak Street Remodel',status:'Checked out',tone:'',updated:'8 min ago'},{id:'table-saw',name:'DeWalt Table Saw',label:'FM-0311',place:'Oak Street Remodel',status:'On site',tone:'',updated:'21 min ago'},{id:'multimeter',name:'Fluke Multimeter',label:'FM-0190',place:'Main Shop',status:'Available',tone:'gray',updated:'1 hr ago'}],
    workers:[{name:'Jordan Hill',role:'Field worker',tools:3,last:'Checked out M18 Drill · 8m ago'},{name:'Casey Wu',role:'Field worker',tools:1,last:'Returned Multimeter · 1h ago'}],
    locations:[{name:'Main Shop',type:'Shop'},{name:'Oak Street Remodel',type:'Job site'},{name:'Van 2',type:'Truck'}],
    damage:[],maintenance:[],activity:[{text:'Milwaukee M18 Drill checked out to Jordan Hill',place:'Oak Street Remodel',time:'8 min ago'},{text:'DeWalt Table Saw moved to Oak Street Remodel',place:'Oak Street Remodel',time:'21 min ago'},{text:'Fluke Multimeter returned to Main Shop',place:'Main Shop',time:'1 hr ago'}]
  };
  const escape=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
  const clone=value=>JSON.parse(JSON.stringify(value));
  function state(){try{const saved=JSON.parse(localStorage.getItem(key));return saved?{...clone(defaults),...saved}:clone(defaults)}catch{return clone(defaults)}}
  const save=data=>localStorage.setItem(key,JSON.stringify(data));
  function activity(data,text,place){data.activity.unshift({text,place,time:'Just now'});data.activity=data.activity.slice(0,20)}
  function dialog(content,onSubmit){const node=document.createElement('dialog');node.className='tool-dialog';node.innerHTML=`<form method="dialog"><button class="dialog-close" value="cancel" aria-label="Close">×</button>${content}</form>`;document.body.append(node);node.showModal();node.querySelector('form').addEventListener('submit',event=>{event.preventDefault();if(onSubmit(new FormData(event.currentTarget))!==false){node.close();node.remove()}},{once:true})}
  function renderTools(filter=''){const body=document.getElementById('toolRows');if(!body)return;const needle=filter.trim().toLowerCase();const tools=state().tools.filter(tool=>[tool.name,tool.label,tool.place,tool.status].join(' ').toLowerCase().includes(needle));body.innerHTML=tools.length?tools.map(tool=>`<tr><td><b>${escape(tool.name)}</b><br><small>${escape(tool.label)}</small></td><td>${escape(tool.place)}</td><td><span class="badge ${tool.tone}">${escape(tool.status)}</span></td><td>${escape(tool.updated)}</td><td>${tool.id==='m18-drill'?'<a class="app-action" href="/app/tools/m18-drill/">Open</a>':'<button class="app-action" type="button">Open</button>'}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">No tools match that search.</td></tr>'}
  function renderDashboard(){const body=document.getElementById('activityRows');if(!body)return;body.innerHTML=state().activity.slice(0,4).map(item=>`<tr><td><b>${escape(item.text)}</b></td><td><span class="badge gray">${escape(item.place)}</span></td><td>${escape(item.time)}</td><td><a class="app-action" href="/app/activity/">View</a></td></tr>`).join('')}
  function renderActivity(){const body=document.getElementById('fullActivityRows');if(!body)return;body.innerHTML=state().activity.map(item=>`<tr><td><b>${escape(item.text)}</b></td><td>${escape(item.place)}</td><td>${escape(item.time)}</td></tr>`).join('')}
  function renderWorkers(){const body=document.getElementById('workerRows');if(!body)return;body.innerHTML=state().workers.map(worker=>`<tr><td><b>${escape(worker.name)}</b><br><small>${escape(worker.role)}</small></td><td>${escape(worker.tools)}</td><td>${escape(worker.last)}</td><td><button class="app-action" type="button">Open</button></td></tr>`).join('')}
  function renderLocations(){const body=document.getElementById('locationRows');if(!body)return;const data=state();body.innerHTML=data.locations.map(location=>{const count=data.tools.filter(tool=>tool.place.includes(location.name)).length;return `<tr><td><b>${escape(location.name)}</b></td><td>${escape(location.type)}</td><td>${count}</td><td>${count?'Recently updated':'No activity yet'}</td></tr>`}).join('')}
  function renderDamage(){const root=document.getElementById('damageContent');if(!root)return;const data=state();root.innerHTML=data.damage.length?`<div class="app-card"><table class="app-table"><thead><tr><th>Tool</th><th>Report</th><th>Status</th><th>Time</th></tr></thead><tbody>${data.damage.map(item=>`<tr><td><b>${escape(item.tool)}</b></td><td>${escape(item.note)}</td><td><span class="badge warn">Needs inspection</span></td><td>${escape(item.time)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="app-card empty"><h2>No open damage reports</h2><p>Report a problem before another crew member relies on the tool.</p></div>'}
  function openToolForm(){dialog('<p class="eyebrow">NEW TOOL</p><h2>Add a tool</h2><p>Start with the name and label ID. You can add details later.</p><label>Tool name<input name="name" required maxlength="80" placeholder="e.g. Bosch Rotary Hammer"></label><label>Label ID<input name="label" required maxlength="40" placeholder="e.g. FM-1843"></label><label>Starting location<select name="place"><option>Main Shop</option><option>Oak Street Remodel</option><option>Van 2</option></select></label><button class="button">Add tool <span>→</span></button>',form=>{const name=form.get('name').trim(),label=form.get('label').trim(),place=form.get('place');if(!name||!label)return false;const data=state();if(data.tools.some(tool=>tool.label.toLowerCase()===label.toLowerCase())){showToast('That label ID is already in use.');return false}data.tools.unshift({id:'custom-'+Date.now(),name,label,place,status:'Available',tone:'gray',updated:'Just now'});activity(data,`${name} added to the workspace`,place);save(data);renderTools();renderDashboard();renderLocations();showToast(`${name} is ready for a QR label.`)})}
  function openWorkerForm(){dialog('<p class="eyebrow">NEW WORKER</p><h2>Add a crew member</h2><p>Field workers do not change your plan price.</p><label>Name<input name="name" required maxlength="80" placeholder="e.g. Morgan Lee"></label><label>Role<select name="role"><option>Field worker</option><option>Supervisor</option><option>Tool room</option></select></label><button class="button">Add worker <span>→</span></button>',form=>{const name=form.get('name').trim(),role=form.get('role');if(!name)return false;const data=state();data.workers.unshift({name,role,tools:0,last:'No activity yet'});activity(data,`${name} added as ${role}`, 'Team');save(data);renderWorkers();renderDashboard();showToast(`${name} is ready to use Fieldmark.`)})}
  function openLocationForm(){dialog('<p class="eyebrow">NEW LOCATION</p><h2>Add a location</h2><p>Use a name that makes sense to the crew in the field.</p><label>Location name<input name="name" required maxlength="80" placeholder="e.g. Cedar Street Site"></label><label>Type<select name="type"><option>Job site</option><option>Shop</option><option>Truck</option></select></label><button class="button">Add location <span>→</span></button>',form=>{const name=form.get('name').trim(),type=form.get('type');if(!name)return false;const data=state();data.locations.unshift({name,type});activity(data,`${name} added as a ${type}`,name);save(data);renderLocations();renderDashboard();showToast(`${name} is ready for tool moves.`)})}
  function reportDamage(){dialog('<p class="eyebrow">DAMAGE REPORT</p><h2>Report an issue</h2><label>Tool<select name="tool">'+state().tools.map(tool=>`<option>${escape(tool.name)}</option>`).join('')+'</select></label><label>What happened?<input name="note" required maxlength="140" placeholder="e.g. Blade guard sticking"></label><button class="button">Save report <span>→</span></button>',form=>{const tool=form.get('tool'),note=form.get('note').trim();if(!note)return false;const data=state();data.damage.unshift({tool,note,time:'Just now'});const record=data.tools.find(item=>item.name===tool);if(record){record.status='Needs inspection';record.tone='warn';record.updated='Just now'}activity(data,`${tool} reported damaged`, 'Needs inspection');save(data);renderDamage();renderTools();renderDashboard();showToast('Damage report saved and tool marked for inspection.')})}
  function importCsv(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{const rows=parseCsv(String(reader.result));if(rows.length<2){showToast('Use a CSV with a header row and at least one tool.');return}const heads=rows[0].map(value=>value.trim().toLowerCase());const nameIndex=heads.findIndex(value=>['name','tool name','tool'].includes(value));const labelIndex=heads.findIndex(value=>['asset id','label id','label','id'].includes(value));const locationIndex=heads.findIndex(value=>['location','current location'].includes(value));if(nameIndex<0){showToast('The CSV needs a Name or Tool name column.');return}const data=state();let added=0;rows.slice(1).forEach((row,index)=>{const name=(row[nameIndex]||'').trim();if(!name)return;const label=(row[labelIndex]||`FM-IMPORT-${data.tools.length+index+1}`).trim();if(data.tools.some(tool=>tool.label.toLowerCase()===label.toLowerCase()))return;const place=(row[locationIndex]||'Main Shop').trim();data.tools.push({id:'import-'+Date.now()+'-'+index,name,label,place,status:'Available',tone:'gray',updated:'Just now'});added++});if(!added){showToast('No new tool labels were found in that file.');return}activity(data,`${added} tool${added===1?'':'s'} imported from ${file.name}`, 'Import');save(data);renderTools();renderDashboard();renderLocations();showToast(`${added} tool${added===1?'':'s'} imported and ready for labels.`)};reader.readAsText(file)}
  function parseCsv(text){const rows=[],row=[];let cell='',quoted=false;for(let i=0;i<text.length;i++){const char=text[i],next=text[i+1];if(char==='"'&&quoted&&next==='"'){cell+='"';i++}else if(char==='"'){quoted=!quoted}else if(char===','&&!quoted){row.push(cell);cell=''}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&next==='\n')i++;row.push(cell);if(row.some(value=>value.length))rows.push(row.splice(0));cell=''}else{cell+=char}}row.push(cell);if(row.some(value=>value.length))rows.push(row);return rows}
  function changeM18(action){const data=state(),tool=data.tools.find(item=>item.id==='m18-drill');if(!tool)return;const update={take:{place:'Jordan Hill · Oak Street Remodel',status:'Checked out',tone:'',text:'Milwaukee M18 Drill checked out to Jordan Hill'},move:{place:'Van 2',status:'In transfer',tone:'warn',text:'Milwaukee M18 Drill moved to Van 2'},return:{place:'Main Shop',status:'Available',tone:'gray',text:'Milwaukee M18 Drill returned to Main Shop'}}[action];Object.assign(tool,update,{updated:'Just now'});activity(data,update.text,update.place);save(data);renderTools();renderDashboard();renderLocations();renderDetail();showToast(update.text+'.')}
  function renderDetail(){const root=document.getElementById('toolDetail');if(!root)return;const tool=state().tools.find(item=>item.id==='m18-drill');if(!tool)return;root.innerHTML=`<div class="detail-heading"><div><p class="eyebrow">${escape(tool.label)}</p><h1>${escape(tool.name)}</h1><p>${escape(tool.place)}</p></div><span class="badge ${tool.tone}">${escape(tool.status)}</span></div><div class="detail-grid"><section class="app-card detail-card"><h2>Next action</h2><p>Record the handoff that is happening now.</p><div class="detail-actions"><button class="button" onclick="FieldmarkDemo.changeM18('take')">Take tool</button><button class="button outline" onclick="FieldmarkDemo.changeM18('move')">Move tool</button><button class="button outline" onclick="FieldmarkDemo.changeM18('return')">Return to shop</button></div></section><section class="app-card detail-card"><h2>Tool details</h2><dl><div><dt>Label ID</dt><dd>${escape(tool.label)}</dd></div><div><dt>Current record</dt><dd>${escape(tool.place)}</dd></div><div><dt>Condition</dt><dd>${tool.tone==='warn'?'Needs inspection':'Ready to use'}</dd></div></dl></section></div><section class="app-card detail-card history"><h2>Activity history</h2>${state().activity.filter(item=>item.text.includes('Milwaukee')).map(item=>`<div><b>${escape(item.text)}</b><span>${escape(item.time)}</span></div>`).join('')||'<p>No activity yet.</p>'}</section>`}
  function renderMaintenance(){const root=document.getElementById('maintenanceContent');if(!root)return;const data=state();root.innerHTML=data.maintenance.length?`<div class="app-card"><table class="app-table"><thead><tr><th>Tool</th><th>Work needed</th><th>Status</th><th>Time</th></tr></thead><tbody>${data.maintenance.map(item=>`<tr><td><b>${escape(item.tool)}</b></td><td>${escape(item.note)}</td><td><span class="badge warn">Scheduled</span></td><td>${escape(item.time)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="app-card empty"><h2>No scheduled maintenance</h2><p>Schedule a check before a damaged tool returns to circulation.</p></div>'}
  function scheduleMaintenance(){dialog('<p class="eyebrow">MAINTENANCE</p><h2>Schedule maintenance</h2><label>Tool<select name="tool">'+state().tools.map(tool=>`<option>${escape(tool.name)}</option>`).join('')+'</select></label><label>Work needed<input name="note" required maxlength="140" placeholder="e.g. Replace worn blade guard"></label><button class="button">Schedule work <span>→</span></button>',form=>{const tool=form.get('tool'),note=form.get('note').trim();if(!note)return false;const data=state();data.maintenance.unshift({tool,note,time:'Just now'});const record=data.tools.find(item=>item.name===tool);if(record){record.status='Maintenance scheduled';record.tone='warn';record.updated='Just now'}activity(data,`${tool} scheduled for maintenance`, 'Maintenance');save(data);renderMaintenance();renderTools();renderDashboard();showToast('Maintenance scheduled and tool marked for attention.')})}
  function ready(){renderTools();renderDashboard();renderActivity();renderWorkers();renderLocations();renderDamage();renderMaintenance();renderDetail();const toolSearch=document.querySelector('[data-tool-search]');if(toolSearch)toolSearch.addEventListener('input',event=>renderTools(event.target.value));const csv=document.querySelector('[data-csv-import]');if(csv)csv.addEventListener('change',event=>importCsv(event.target.files[0]))}
  return{ready,openToolForm,openWorkerForm,openLocationForm,reportDamage,scheduleMaintenance,importCsv,changeM18};
})();
document.addEventListener('DOMContentLoaded',FieldmarkDemo.ready);
